const courses = [
 {name:'Speaking',color:'blue',icon:'chat',description:'Improve speaking skills and communicate naturally.',intro:'Find your voice, one conversation at a time.',topics:['Everyday conversations and useful expressions','Clear pronunciation and natural rhythm','Sharing ideas and asking questions'],practice:'Guided conversations, role-play and speaking prompts help you practise English in situations you recognise.'},
 {name:'Listening',color:'yellow',icon:'headphones',description:'Understand everyday English with greater confidence.',intro:'Listen closely. Understand more.',topics:['Recognising key words and main ideas','Following conversations and instructions','Listening for detail and meaning'],practice:'Build understanding with focused listening activities and everyday dialogue.'},
 {name:'Reading',color:'mint',icon:'book',description:'Develop vocabulary and reading comprehension.',intro:'Open a book. Open up possibilities.',topics:['Understanding the main idea of a text','Building vocabulary in context','Finding information and making connections'],practice:'Explore short texts and practical reading tasks, with support to understand unfamiliar words.'},
 {name:'Writing',color:'pink',icon:'pencil',description:'Express ideas clearly and accurately.',intro:'Put your ideas into words.',topics:['Building clear sentences and paragraphs','Organising ideas for different audiences','Writing everyday messages and emails'],practice:'Use structured prompts and revision activities to develop clear, purposeful writing.'},
 {name:'Grammar',color:'orange',icon:'star',description:'Build a strong foundation in English grammar.',intro:'Make sense of how English works.',topics:['Sentence structure and word order','Using tenses in everyday communication','Applying grammar in speech and writing'],practice:'Connect grammar to real examples and practise using it in meaningful sentences.'}
];
function icon(name){const paths={chat:'M9 12Q30 1 51 12v26Q31 49 20 40L7 51l3-17Z M19 20h23M19 28h17',headphones:'M10 35V26a20 20 0 0140 0v10M9 31h9v20H9q-5-10 0-20ZM43 31h9q5 10 0 20h-9Z',book:'M6 12q12-4 24 4 12-8 24-4v35q-12-4-24 4-12-8-24-4Z M30 16v35',pencil:'M12 44 39 7l12 10-27 37-16 4Z M35 13l12 10M12 44l12 10M19 44l22-29',star:'m30 5 6 17 18-6-11 16 12 15-20-4-7 15-4-19-20 1 17-12-7-16Z',arrow:'M9 46q38 2 31-30M23 22l18-9 10 17',heart:'M30 49S1 32 7 16q8-16 23 1 15-17 23-1 6 16-23 33Z',steps:'M7 50h14V36h14V22h14V8M30 8h19v19'};return `<svg class="draw-icon" viewBox="0 0 60 64" aria-hidden="true"><path d="${paths[name]||paths.star}"/></svg>`}
function heading(accent,title,description='',extra=''){return `<div class="section-heading ${extra}"><p class="hand eyebrow">${accent}</p><h2>${title}</h2>${description?`<p>${description}</p>`:''}</div>`}
function galleryArt(i){const bg=['#e6eee0','#f5e3d9','#f1e9d6','#ddeaf0','#ece3f1','#e7eccc','#e6eee0','#f5e3d9'][i];const scenes=[`<rect x="85" y="30" width="230" height="130" rx="8" fill="#fffdf5"/><path d="M107 61h86m-86 25h156m-156 25h120" stroke="#8caf9f"/><path d="M35 205h330M60 205v52m280-52v52"/><circle cx="133" cy="183" r="23" fill="#d4a080"/><path d="M94 250v-27q38-30 77 0v27" fill="#7a9e8c"/><circle cx="272" cy="180" r="23" fill="#c99068"/><path d="M234 250v-28q38-30 77 0v28" fill="#cf9bbb"/>`,`<ellipse cx="200" cy="177" rx="140" ry="45" fill="#fbf6e4"/><path d="M120 205v40m160-40v40"/>${[95,200,305].map((x,j)=>`<circle cx="${x}" cy="95" r="25" fill="#deb08c"/><path d="M${x-34} 165v-33q34-25 68 0v33" fill="${['#d298ad','#90b4a0','#e9c565'][j]}"/>`).join('')}<path d="M150 164l60-10 35 25-65 10Z" fill="#dce8f3"/>`,`<path d="M81 80 198 65l14 148-115 13Z" fill="#8fac95"/><path d="M94 90 182 80m-85 22 88-11" stroke="#fff8de"/><path d="M180 53 299 78l-31 157-120-27Z" fill="#fffdf6"/><path d="M204 89l65 14m-70 7 65 14m-70 7 52 12" stroke="#a4b8b3"/><path d="m296 161 12-61 10 2-12 61-8 13Z" fill="#ebba58"/>`,`<rect x="56" y="32" width="131" height="124" rx="3" fill="#f9fbf1"/><path d="M121 32v124M56 95h131" stroke="#96b2a6"/><path d="M98 201h238M130 201v55m169-55v55"/><path d="M256 195v-41m-17 0h35l-5 40h-24Z" fill="#d1ab89"/><path d="M256 159q-55-32-22-50 24 3 22 50 2-62 30-51 15 29-30 51" fill="#7b9f79"/>`,`<path d="M64 90q136-90 272 0" stroke="#e0b94f"/><path d="m98 71 9 24 15-32m63-12 15 26 15-25m67 12 12 25 11-16" fill="#e5b857"/>${[90,164,238,312].map((x,j)=>`<circle cx="${x}" cy="148" r="24" fill="#dbaa86"/><path d="M${x-31} 244v-60q31-27 62 0v60" fill="${['#d59bbb','#85a58e','#dfbd62','#92b7d1'][j]}"/>`).join('')}`,`<path d="M96 79 282 65l12 157-188 13Z" fill="#fffdf4"/><text x="195" y="113" text-anchor="middle" font-family="Kalam,cursive" font-size="23" stroke="none" fill="#214c3e">Small steps.</text><text x="200" y="149" text-anchor="middle" font-family="Kalam,cursive" font-size="23" stroke="none" fill="#214c3e">Big progress.</text><path d="M191 181q-18-20-22-5 0 10 22 23 24-20 20-27-11-9-20 9" stroke="#d5825b"/>`];return `<svg viewBox="0 0 400 280" role="img" aria-label="Illustrated gallery placeholder"><rect width="400" height="280" fill="${bg}"/><g stroke="#36574c" stroke-width="3" fill="none" stroke-linecap="round" stroke-linejoin="round">${scenes[i%6]}</g></svg>`}
const features=[['Practical learning','Learn English through useful real-world situations.','book'],['Supportive teaching','A welcoming environment designed to help learners progress.','heart'],['Communication focused','Build confidence in speaking and understanding English.','chat'],['Step-by-step progress','Develop skills through clear and structured learning.','steps']];
document.querySelector('#sections').innerHTML=`
<section id="courses" class="section courses-section">${heading('Our Courses','Build your English<br>step by step.','Develop practical English skills through structured, engaging lessons designed for confident communication.')}<span class="section-doodle hand" aria-hidden="true">a little better,<br>every day ↙</span><div class="course-grid">${courses.map((c,i)=>`<button class="course-card ${c.color} reveal" data-course="${i}" aria-label="Learn more about ${c.name}"><div class="card-top"><span>0${i+1}</span>${icon(c.icon)}</div><h3>${c.name}</h3><p>${c.description}</p><span class="card-link">Explore course <span>↗</span></span></button>`).join('')}</div></section>
<section id="about" class="section about-section"><div class="about-art reveal"><div class="about-art-header"><span class="hand">Good things take practice.</span><span aria-hidden="true">✳</span></div>${galleryArt(0)}<span class="about-sticker hand">A place to learn.<br>A space to grow. ♡</span></div><div class="about-copy reveal">${heading('About Evangel','More than<br>just classes.')}<p>Evangel Learning Institute is focused on helping learners strengthen their English skills through practical, supportive and engaging learning experiences.</p><p>Learn with purpose. Practise with confidence. Take your next step in English.</p><a class="button" href="#about-more" id="about-link">Learn more about us <span>↗</span></a><div id="about-more" hidden><h3>Learning that connects to everyday life</h3><p>Our approach brings speaking, listening, reading, writing and grammar together. Explore each skill, then contact us to discuss your learning goals and the class options available.</p></div></div></section>
<section class="section why-section">${heading('The Evangel approach','A little support.<br>A lot of possibility.')}<div class="feature-grid">${features.map(([title,copy,img])=>`<article class="feature-card reveal">${icon(img)}<h3>${title}</h3><p>${copy}</p></article>`).join('')}</div></section>
<section id="gallery" class="section gallery-section">${heading('Our Gallery','Moments that<br>inspire us','Discover moments from the Evangel Learning Institute community.')}<p class="gallery-notice">A glimpse of what’s to come — illustrations shown until our community photos arrive.</p><div class="gallery-grid" id="gallery-grid"></div><button class="button outline" id="more-photos" aria-expanded="false" aria-controls="gallery-grid">View more photos <span>↗</span></button></section>
<section class="journey"><div class="journey-deco" aria-hidden="true">${icon('book')}<span class="hand">Your next chapter ↗</span></div><div>${heading('Start Today','Your English journey<br>starts here.','Take the next step toward clearer communication and greater confidence in English.')}<a class="button" href="#contact">Join Evangel <span>↗</span></a></div><div class="journey-star" aria-hidden="true">✳</div></section>
<section id="contact" class="section contact-section"><div class="contact-copy">${heading('Get in Touch',"We’d love to<br>hear from you.","Have a question or want to learn more about our classes? Send us a message and we’ll get back to you.")}<div id="contact-details"></div><div class="contact-doodle hand">Big dreams start<br>with a little hello. <span>♡</span>${icon('arrow')}</div></div><form id="contact-form" novalidate><div class="form-row"><div class="field"><label for="name">Your name <span>*</span></label><input id="name" name="name" autocomplete="name" placeholder="Enter your name" required maxlength="120" aria-describedby="name-error"><span class="field-error" id="name-error"></span></div><div class="field"><label for="email">Email address <span>*</span></label><input id="email" name="email" type="email" autocomplete="email" placeholder="Enter your email" required maxlength="254" aria-describedby="email-error"><span class="field-error" id="email-error"></span></div></div><div class="form-row"><div class="field"><label for="phone">Phone number <small>(optional)</small></label><input id="phone" name="phone" type="tel" autocomplete="tel" placeholder="Enter your phone number" maxlength="40"></div><div class="field"><label for="interest">I’m interested in</label><select id="interest" name="interest"><option value="">Select a course</option>${courses.map(c=>`<option>${c.name}</option>`).join('')}<option>General Enquiry</option></select></div></div><div class="field"><label for="message">Message <span>*</span></label><textarea id="message" name="message" rows="4" placeholder="Type your message…" required maxlength="5000" aria-describedby="message-error"></textarea><span class="field-error" id="message-error"></span></div><p class="form-note" id="availability-note"></p><button class="button" type="submit">Send message <span>↗</span></button><p id="form-status" role="status" aria-live="polite" tabindex="-1"></p></form></section>`;
document.querySelector('#footer-root').innerHTML=`<footer><div class="footer-grid"><div><a class="brand" href="#home" aria-label="EVANGEL LEARNING INSTITUTE home">${document.querySelector('.brand').innerHTML}</a><p class="hand footer-tagline">Better English.<br>Brighter Future.</p><p>Practical learning for<br>confident communication.</p><div id="social-links"></div></div><div><h3>Quick links</h3>${['Home','Courses','Gallery','About','Contact'].map(n=>`<a href="#${n.toLowerCase()}">${n}</a>`).join('')}</div><div><h3>Courses</h3>${courses.map((c,i)=>`<button data-course="${i}">${c.name}</button>`).join('')}</div><div><h3>Contact</h3><div id="footer-contact"></div><a href="#contact">Enquire about classes ↗</a><p class="hand footer-scribble">Small steps.<br>Big dreams. <span>✧</span></p></div></div><div class="footer-bottom"><span>© 2026 Evangel Learning Institute. All rights reserved.</span><div><button data-policy="privacy">Privacy Policy</button><button data-policy="terms">Terms of Service</button></div></div></footer>`;
const dialog=document.querySelector('#detail-dialog');
function showDialog(html){document.querySelector('#dialog-content').innerHTML=html;dialog.showModal();document.body.classList.add('modal-open')}
function closeDialog(){dialog.close();document.body.classList.remove('modal-open')}
dialog.querySelector('.close-dialog').addEventListener('click',closeDialog);dialog.addEventListener('close',()=>document.body.classList.remove('modal-open'));dialog.addEventListener('click',e=>{if(e.target===dialog){const b=dialog.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)closeDialog()}});
document.addEventListener('click',e=>{const course=e.target.closest('[data-course]');if(course){const c=courses[Number(course.dataset.course)];showDialog(`<div class="dialog-icon ${c.color}">${icon(c.icon)}</div><p class="hand eyebrow">Your next step</p><h2 id="dialog-title">${c.name}</h2><p class="dialog-intro">${c.intro}</p><h3>What you’ll practise</h3><ul>${c.topics.map(t=>`<li>${t}</li>`).join('')}</ul><p>${c.practice}</p><p class="muted">Contact us for class availability, levels, schedules and fees.</p><button class="button" id="course-enquiry">Enquire about ${c.name.toLowerCase()} <span>↗</span></button>`);document.querySelector('#course-enquiry').addEventListener('click',()=>{closeDialog();document.querySelector('#interest').value=c.name;location.hash='contact';document.querySelector('#name').focus({preventScroll:true})})}});
document.querySelector('#about-link').addEventListener('click',()=>{document.querySelector('#about-more').hidden=false});
const categories=['Class sessions','Group activities','Learning materials','Our space','Moments together','Learning materials','Class sessions','Group activities'];
let galleryExpanded=false;
function validImage(src){try{const u=new URL(src,location.origin);return ['https:','http:'].includes(u.protocol)}catch{return false}}
const galleryItems=config.gallery.filter(g=>g.src&&validImage(g.src));
function renderGallery(){const items=galleryItems.length?galleryItems:categories.map((category,i)=>({category,placeholder:true,index:i}));document.querySelector('#gallery-grid').innerHTML=items.slice(0,galleryExpanded?items.length:6).map((g,i)=>`<button class="gallery-card" data-photo="${i}" aria-label="View ${esc(g.category)}${g.placeholder?' illustration':''}"><div class="gallery-image">${g.placeholder?galleryArt(g.index):`<img src="${esc(g.src)}" alt="${esc(g.alt||g.category)}" loading="lazy" width="400" height="280">`}</div><span class="gallery-label ${courses[i%5].color}">${esc(g.category)}</span>${g.placeholder?'<span class="placeholder-tag">Illustration</span>':''}</button>`).join('');const more=document.querySelector('#more-photos');more.hidden=items.length<=6;more.setAttribute('aria-expanded',String(galleryExpanded));more.innerHTML=galleryExpanded?'Show fewer photos <span>↑</span>':'View more photos <span>↗</span>';}
renderGallery();document.querySelector('#more-photos').addEventListener('click',()=>{galleryExpanded=!galleryExpanded;renderGallery()});document.querySelector('#gallery-grid').addEventListener('click',e=>{const el=e.target.closest('[data-photo]');if(!el)return;const i=Number(el.dataset.photo),g=galleryItems[i];showDialog(`<h2 id="dialog-title">${esc(g?.category||categories[i])}</h2><div class="lightbox-image">${g?`<img src="${esc(g.src)}" alt="${esc(g.alt||g.category)}">`:galleryArt(i)}</div>${!g?'<p class="muted">Illustrated placeholder. Real EVANGEL LEARNING INSTITUTE community photos will appear here when available.</p>':''}`)});
const contact=config.contact;
const contactHTML=[contact.email?`<a href="mailto:${esc(contact.email)}">${esc(contact.email)}</a>`:'',contact.phone?`<a href="tel:${esc(contact.phone.replace(/[^+\d]/g,''))}">${esc(contact.phone)}</a>`:'',contact.address?`<p>${esc(contact.address)}</p>`:'',contact.hours?`<p>${esc(contact.hours)}</p>`:''].join('');
document.querySelector('#contact-details').innerHTML=contactHTML;document.querySelector('#footer-contact').innerHTML=contactHTML;
document.querySelector('#social-links').innerHTML=Object.entries(config.social).filter(([label,url])=>{try{return new URL(url).protocol==='https:'}catch{return false}}).map(([label,url])=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`).join('');
if(config.canonicalUrl){try{const u=new URL(config.canonicalUrl);if(u.protocol==='https:'){const link=document.createElement('link');link.rel='canonical';link.href=u.href;document.head.append(link);const meta=document.createElement('meta');meta.setAttribute('property','og:url');meta.content=u.href;document.head.append(meta)}}catch{}}
const form=document.querySelector('#contact-form'),status=document.querySelector('#form-status'),submit=form.querySelector('[type=submit]');
document.querySelector('#availability-note').textContent=config.contactEndpoint?'Fields marked * are required.':'Online enquiries are not available yet. Your message will not be sent until this service is connected.';
function validateField(field){let error='';if(!field.value.trim())error=({name:'Please enter your name.',email:'Please enter your email address.',message:'Please write a message.'})[field.name]||'';else if(field.name==='email'&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(field.value.trim()))error='Please enter a valid email address, such as name@example.com.';field.setAttribute('aria-invalid',String(!!error));document.querySelector(`#${field.name}-error`).textContent=error;return !error}
form.querySelectorAll('[required]').forEach(field=>{field.addEventListener('blur',()=>validateField(field));field.addEventListener('input',()=>{if(field.getAttribute('aria-invalid')==='true')validateField(field)})});
// Isolated submission adapter. A missing service must never report success.
async function submitEnquiry(payload){if(!config.contactEndpoint)throw new Error('Your message has not been sent. Online enquiries are not available yet. Please try again when the service is available.');const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),15000);try{const response=await fetch(config.contactEndpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload),signal:controller.signal});if(!response.ok)throw new Error('We couldn’t send your message. Please try again in a moment.');return true}finally{clearTimeout(timer)}}
let submitting=false;
form.addEventListener('submit',async e=>{e.preventDefault();if(submitting)return;const fields=[...form.querySelectorAll('[required]')];const checks=fields.map(validateField);if(checks.includes(false)){fields[checks.indexOf(false)].focus();status.textContent='Please check the highlighted fields.';return}submitting=true;submit.disabled=true;submit.innerHTML='Sending…';form.setAttribute('aria-busy','true');status.textContent='';try{const payload=Object.fromEntries(new FormData(form));Object.keys(payload).forEach(k=>payload[k]=payload[k].trim());await submitEnquiry(payload);status.textContent='Thank you! Your enquiry has been sent. We’ll be in touch soon.';status.className='success';form.reset()}catch(error){status.textContent=error.name==='AbortError'?'The request timed out. Your message may not have been received. Please try again.':error.message;status.className='error'}finally{submitting=false;submit.disabled=false;submit.innerHTML='Send message <span>↗</span>';form.removeAttribute('aria-busy');status.focus({preventScroll:true})}});
document.querySelectorAll('[data-policy]').forEach(b=>b.addEventListener('click',()=>{const privacy=b.dataset.policy==='privacy';showDialog(`<p class="hand eyebrow">Website information</p><h2 id="dialog-title">${privacy?'Privacy Policy':'Terms of Service'}</h2>${privacy?'<p>This website does not use analytics or advertising trackers. Form entries are not saved in browser storage.</p><p>When online enquiries are enabled, the form sends the details you enter to the configured enquiry service. Do not include sensitive information in your message.</p><p>Fonts are loaded from Google Fonts, which receives a standard web request from your browser. The website host may process routine access logs.</p><p>The institute’s full privacy notice, including contact details and retention practices, will be added before online enquiries open.</p>':'<p>This website provides general information about English learning at EVANGEL LEARNING INSTITUTE. Enquiring about a course does not confirm enrolment.</p><p>Class availability, schedules, fees and enrolment conditions must be confirmed directly with the institute. Illustrations in the gallery are placeholders and do not depict actual classes or students.</p><p>Full enrolment terms will be provided by the institute before registration or payment.</p>'}`)}));
const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in-view');observer.unobserve(e.target)}}),{threshold:.1});document.querySelectorAll('.reveal').forEach((el,i)=>{el.style.setProperty('--delay',`${i%5*65}ms`);observer.observe(el)});
const navObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting)document.querySelectorAll('header nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+e.target.id))}),{rootMargin:'-15% 0px -60% 0px'});document.querySelectorAll('main section[id]').forEach(el=>navObserver.observe(el));

